create table public.inventory_reservations (id uuid primary key default gen_random_uuid(), store_id uuid not null, order_id uuid not null, location_id uuid not null, variant_id uuid not null, quantity integer not null check(quantity > 0), status text not null default 'reserved' check(status in ('reserved','committed','released','expired')), expires_at timestamptz not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(store_id,order_id) references public.orders(store_id,id) on delete cascade, foreign key(store_id,location_id) references public.inventory_locations(store_id,id), foreign key(store_id,variant_id) references public.product_variants(store_id,id));
create index idx_reservations_expiry on public.inventory_reservations(expires_at) where status='reserved';
